Section PcdOk.
Context {SCFG_P : ScfgP}.
Variable L : asan_layout.
Variable ar : asan_run.
Variable C : asan_statics_cells.
Variable HI : asan_iface.
Variable IL0 : icpt_layout.
Abbreviation IC := PMLA.C_xasan.
Hypothesis HIok : PmHeapIfaceA.asan_iface_ok L ar C SCFG HI.
Hypothesis LAY : L5A.as0_layout L C.
Hypothesis SM0 : hl_stack_malloc L 0 = PDA.PC_SM.
Hypothesis FOOTC : forall a, PMLA.in_foot IC a -> ~ hl_rt_static L a.
Hypothesis ISH : rt_img_shadow L IL0 HI.
Hypothesis POI2 : Forall (fun r : Z * Z => PDA.SLOT2 + 8 <= fst r \/ snd r <= PDA.SLOT2) (icl_poison IL0).
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PMSA.fp_ok fx -> PMSA.fp_ok fx'.
Hypothesis ERRH_OK : PMSA.errh_specA L ar HI PDA.PC_ERRH.
Hypothesis SETEC_OK : PMSA.set_ec_specA L ar HI IC PDA.PC_SETEC.

Definition hid (P : Prop) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$P;Rw#1").
Definition WF (P a : Z) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$P;R+?$a;R+?!2+a[!2+_T!2'`;!2'_B#2!1,0|748;#1!2'aF#1!2'_B#2!1,0|750;!3+_K+?#1!2'_B#2!1,0|753;").
